"""Compile submitted Go stdlib client, then authenticate directly to an owned real API."""
import json,os,pathlib,subprocess,tempfile

DRIVER='''package main
import("bytes";"crypto/tls";"crypto/x509";"encoding/json";"fmt";"io";"net/http";"os";"strings";"time")
type Input struct {Server string;CA string;Cert string;Key string;Path string;UID string;Generation int64;Initial map[string]any;Attempts int}
type Trace struct {Method string `json:"method"`;Path string `json:"path"`;Status int `json:"status"`}
func main(){
 var c Input;decoder:=json.NewDecoder(os.Stdin);decoder.UseNumber();if err:=decoder.Decode(&c);err!=nil{panic(err)}
 pem,err:=os.ReadFile(c.CA);if err!=nil{panic(err)};pool:=x509.NewCertPool();if !pool.AppendCertsFromPEM(pem){panic("private CA unavailable")}
 cert,err:=tls.LoadX509KeyPair(c.Cert,c.Key);if err!=nil{panic(err)}
 transport:=&http.Transport{TLSClientConfig:&tls.Config{RootCAs:pool,Certificates:[]tls.Certificate{cert},MinVersion:tls.VersionTLS12}}
 defer transport.CloseIdleConnections();client:=&http.Client{Transport:transport,Timeout:3*time.Second};trace:=[]Trace{}
 request:=func(method,path string,body map[string]any)(int,map[string]any,error){
  if !strings.HasPrefix(path,"/")||strings.HasPrefix(path,"//"){return 0,nil,fmt.Errorf("explicit private path required")}
  var stream io.Reader
  if body!=nil{raw,e:=json.Marshal(body);if e!=nil{return 0,nil,e};stream=bytes.NewReader(raw)}
  req,e:=http.NewRequest(method,c.Server+path,stream);if e!=nil{return 0,nil,e};req.Header.Set("Content-Type","application/json")
  response,e:=client.Do(req);if e!=nil{return 0,nil,e};defer response.Body.Close();trace=append(trace,Trace{method,path,response.StatusCode})
  value:=map[string]any{};d:=json.NewDecoder(response.Body);d.UseNumber();if e=d.Decode(&value);e!=nil{return response.StatusCode,nil,e}
  return response.StatusCode,value,nil
 }
 result:=map[string]any{}
 __CALL__
 result["requests"]=trace;if callErr!=nil{result["error"]=callErr.Error()}else{result["error"]=""}
 if err:=json.NewEncoder(os.Stdout).Encode(result);err!=nil{panic(err)}
}
'''

class GoClient:
 def __init__(self,call):self.call=call
 def __enter__(self):
  source=pathlib.Path('task.go').read_text(encoding='utf8')
  if 'IMPLEMENT_NATIVE_OPERATION' in source or source.startswith('-- implement'):raise NotImplementedError('implement real Go API operation')
  self.temp=tempfile.TemporaryDirectory(prefix='of-operator-go-build-');self.root=pathlib.Path(self.temp.name)
  for name,content in [('task.go',source),('contract.go',pathlib.Path('contract.go').read_text(encoding='utf8')),('driver.go',DRIVER.replace('__CALL__',self.call))]:(self.root/name).write_text(content,encoding='utf8')
  cache=pathlib.Path('/tmp/of-operator-go-cache');cache.mkdir(exist_ok=True)
  self.env={**os.environ,'GO111MODULE':'off','CGO_ENABLED':'0','GOMAXPROCS':'2','GOMEMLIMIT':'384MiB','GOCACHE':str(cache),'GOTMPDIR':str(self.root)}
  args=['go','build','-trimpath','-buildvcs=false','-o',str(self.root/'client'),*[str(self.root/name) for name in ('task.go','contract.go','driver.go')]]
  result=subprocess.run(args,capture_output=True,text=True,env=self.env,timeout=70)
  assert result.returncode==0,'native submitted Go client did not compile: '+result.stderr[-2400:]
  print('NATIVE_GO_OPERATOR_CLIENT_COMPILED',flush=True);return self
 def run(self,cluster,path,*,uid='',generation=0,initial=None,attempts=2,identity='admin'):
  config=dict(Server=cluster.url,CA=str(cluster.root/'ca.crt'),Cert=str(cluster.root/(identity+'.crt')),Key=str(cluster.root/(identity+'.key')),Path=path,UID=uid,Generation=generation,Initial=initial,Attempts=attempts)
  print('STUDENT_OPERATION_ENTERED:real_operator_go_https_request',flush=True)
  result=subprocess.run([str(self.root/'client')],input=json.dumps(config),capture_output=True,text=True,env=self.env,timeout=15)
  assert result.returncode==0,'actual Go client operation failed: '+result.stderr[-2000:]
  try:return json.loads(result.stdout)
  except ValueError as error:raise AssertionError('actual Go API result missing') from error
 def __exit__(self,*args):
  if hasattr(self,'temp'):self.temp.cleanup()

