  class Handler(BaseHTTPRequestHandler):
   def log_message(self,*args):pass
   def do_POST(self):
    if urlsplit(self.path).path!='/convert':failures.append(urlsplit(self.path).path);self.send_error(404);return
    body=json.loads(self.rfile.read(int(self.headers['Content-Length'])));request=body['request'];desired=request['desiredAPIVersion'];converted=[]
    calls.append(dict(path=self.path,desired=desired,source_versions=[o['apiVersion'] for o in request['objects']]))
