     item=copy.deepcopy(original);source=item['apiVersion'];spec=item['spec']
     if source.endswith('/v1') and desired.endswith('/v2'):spec['message']=spec.pop('text')
     elif source.endswith('/v2') and desired.endswith('/v1'):spec['text']=spec.pop('message')
     item['apiVersion']=desired;converted.append(item)
    result=json.dumps(dict(apiVersion=body['apiVersion'],kind='ConversionReview',response=dict(uid=request['uid'],result=dict(status='Success'),convertedObjects=converted)),ensure_ascii=False).encode()
    self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(result)));self.end_headers();self.wfile.write(result)
  self.http=ThreadingHTTPServer(('127.0.0.1',0),Handler);self.http.daemon_threads=True;context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER);context.load_cert_chain(str(cluster.root/'conversion-webhook.crt'),str(cluster.root/'conversion-webhook.key'));self.http.socket=context.wrap_socket(self.http.socket,server_side=True);self.url='https://127.0.0.1:'+str(self.http.server_port)
  self.thread=threading.Thread(target=self.http.serve_forever,daemon=True);self.thread.start()
